def bubble(arr):
    n = len(arr)

    def swap(arr, i, j):
        arr[i], arr[j] = arr[j], arr[i]
        # print('=>', arr, end=' ')

    for i in range(n - 1):
        for j in range(abs(i - n) - 1):
            if arr[j] > arr[j + 1]:
                swap(arr, j, j + 1)
                # print('j = ' + str(j))

    return arr
